css:
/* =====================================================================
   Fathom for Harbor
   Liquid glass over deep water. theme.js writes the --fx-* variables and the
   html[data-fx-*] switches; everything here reads them.
   Sections:
     1. Variables       5. Wallpaper        9.  Hero (Harbor DOM)
     2. Liquid glass    6. Chrome           10. Harbor surfaces
     3. Our layers      7. Settings panel   11. Performance + motion
     4. Content offsets 8. Posters          12. Fragile overrides (Harbor internals)
   ===================================================================== */

/* 1. Variables ------------------------------------------------------- */
@property --fx-art { syntax: "<color>"; inherits: true; initial-value: #1d4f7a; }

html[data-fx] {
  --fx-h: 255;
  --fx-c: 1;
  --fx-gc: .03;
  --fx-blur: 10px;
  --fx-sat: 185%;
  --fx-frost: .04;
  --fx-rim: .5;
  --fx-radius: 22px;
  --fx-grain: .05;
  --fx-tint: 0%;
  --fx-depth: 1;
  --fx-light: .5;
  --fx-speed: 1;
  --fx-dock-size: 48px;
  --fx-sidebar-w: 220px;
  --fx-top: 0px;
  --fx-wall-dim: .55;
  --fx-on-accent: #07101c;
  --fx-ui: "Hanken Grotesk", "General Sans", system-ui, sans-serif;
  --fx-ease: cubic-bezier(.16, 1, .3, 1);
  --fx-spring: cubic-bezier(.3, 1.35, .45, 1);
}
html[data-fx][data-fx-menubar="on"]:not([data-chrome-hidden]) { --fx-top: 40px; }

/* 2. Liquid glass ------------------------------------------------------
   Clear, lightly blurred, saturated. A thin bright rim catches the light on the
   side facing the pointer (--fx-lg), with darker thickness along the far edge.
   On Chromium, chrome elements also refract their backdrop at the edges
   (backdrop-filter: url(#fx-lens-*), built by theme.js). */
.fx-glass {
  background-color: color-mix(in oklab, var(--fx-art) var(--fx-tint), oklch(.2 var(--fx-gc) var(--fx-h) / var(--fx-ga, .26)));
  background-image: linear-gradient(180deg, rgb(255 255 255 / var(--fx-frost)), rgb(255 255 255 / calc(var(--fx-frost) * .35)));
  -webkit-backdrop-filter: blur(var(--fx-blur)) saturate(var(--fx-sat)) brightness(1.06);
  backdrop-filter: blur(var(--fx-blur)) saturate(var(--fx-sat)) brightness(1.06);
  box-shadow:
    inset 0 0 0 .5px rgb(255 255 255 / calc(var(--fx-rim) * .5)),
    inset 0 1px .5px rgb(255 255 255 / calc(var(--fx-rim) * .85)),
    inset 0 -1px .5px rgb(255 255 255 / calc(var(--fx-rim) * .25)),
    inset 0 -16px 26px -20px rgb(0 0 0 / .45),
    0 18px 44px -16px rgb(0 0 0 / .62),
    0 2px 8px -2px rgb(0 0 0 / .3);
  transition: background-color calc(1.2s / var(--fx-speed)) ease;
}
.fx-glass::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1.2px; pointer-events: none; z-index: 0;
  background: linear-gradient(var(--fx-lg, 160deg), rgb(255 255 255 / calc(var(--fx-rim) * 1.5)) 0%, rgb(255 255 255 / .05) 30%, transparent 55%, rgb(255 255 255 / calc(var(--fx-rim) * .55)) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
}
.fx-glass::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 0;
  background: radial-gradient(130% 70% at 25% -25%, rgb(255 255 255 / calc(var(--fx-rim) * .22)), transparent 60%);
}
.fx-glass.fx-bar::before { display: none; }

html[data-fx-lens="on"] #fx-dock[data-fx-lens-ready] {
  -webkit-backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-dock) saturate(var(--fx-sat)) brightness(1.06);
  backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-dock) saturate(var(--fx-sat)) brightness(1.06); }
html[data-fx-lens="on"] #fx-island[data-fx-lens-ready] {
  -webkit-backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-island) saturate(var(--fx-sat)) brightness(1.06);
  backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-island) saturate(var(--fx-sat)) brightness(1.06); }
html[data-fx-lens="on"] #fx-sidebar[data-fx-lens-ready] {
  -webkit-backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-sidebar) saturate(var(--fx-sat)) brightness(1.06);
  backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-sidebar) saturate(var(--fx-sat)) brightness(1.06); }
html[data-fx-lens="on"] #fx-menubar[data-fx-lens-ready] {
  -webkit-backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-menubar) saturate(var(--fx-sat)) brightness(1.06);
  backdrop-filter: blur(calc(var(--fx-blur) * .6)) url(#fx-lens-menubar) saturate(var(--fx-sat)) brightness(1.06); }

/* 3. Our layers -------------------------------------------------------- */
#fathom-wall { position: fixed; inset: 0; z-index: -29; pointer-events: none; overflow: hidden;
  background-color: oklch(.115 calc(.02 * var(--fx-c)) var(--fx-h)); transition: background-color 1.4s ease; }
#fathom-light { position: fixed; left: 0; top: 0; width: 900px; height: 900px; z-index: 59; pointer-events: none; display: none; opacity: 0;
  border-radius: 50%; will-change: transform; transition: opacity .5s ease;
  background: radial-gradient(closest-side, color-mix(in oklab, var(--color-accent) calc(var(--fx-light) * 16%), transparent), transparent); }
html[data-fx-light="on"] #fathom-light { display: block; }
#fathom-chrome, #fathom-panel, #fathom-toast { font-family: var(--fx-ui); color: var(--color-ink); -webkit-font-smoothing: antialiased; }
#fathom-chrome button, #fathom-panel button, #fathom-panel input, #fathom-toast button { font: inherit; color: inherit; }
#fathom-chrome svg, #fathom-panel svg { display: block; }
html[data-chrome-hidden] #fathom-chrome, html[data-chrome-hidden] #fathom-light { display: none !important; }
#fathom-chrome :focus-visible, #fathom-panel :focus-visible, #fathom-toast :focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
#fathom-filters { position: absolute; width: 0; height: 0; overflow: hidden; }

/* 4. Content offsets ---------------------------------------------------- */
html[data-fx][data-fx-menubar="on"]:not([data-chrome-hidden]) #root { margin-top: var(--fx-top); height: calc(100% - var(--fx-top)); }
html[data-fx][data-fx-chrome="sidebar"]:not([data-chrome-hidden]) main { padding-inline-start: calc(var(--fx-sidebar-w) + 40px) !important; }
html[data-fx][data-fx-chrome="sidebar"][data-fx-compact="on"]:not([data-chrome-hidden]) main { padding-inline-start: 112px !important; }
html[data-fx][data-fx-chrome="dock"][data-fx-dockpos="bottom"]:not([data-chrome-hidden]) main { padding-bottom: calc(var(--fx-dock-size) + 64px) !important; }
html[data-fx][data-fx-chrome="dock"][data-fx-dockpos="left"]:not([data-chrome-hidden]) main { padding-inline-start: calc(var(--fx-dock-size) + 68px) !important; }

/* 5. Wallpaper ---------------------------------------------------------- */
/* The currents drift less than a pixel per frame, so they step about 12 times a second instead of every frame.
   It looks the same, and every glass surface above the wallpaper re-blurs 10x less often. */
#fathom-wall .fx-blob { position: absolute; width: 70vmax; height: 70vmax; border-radius: 50%; will-change: transform;
  -webkit-mask: radial-gradient(closest-side, #000, transparent); mask: radial-gradient(closest-side, #000, transparent);
  transition: background-color 1.4s ease, opacity 1.2s ease;
  animation: fx-drift-1 calc(34s / var(--fx-speed)) steps(420, jump-none) infinite alternate; }
#fathom-wall .fx-b1 { left: -20vmax; top: -30vmax; background-color: oklch(.44 calc(.12 * var(--fx-c)) var(--fx-h) / .55); }
#fathom-wall .fx-b2 { right: -25vmax; top: 10vmax; background-color: oklch(.36 calc(.12 * var(--fx-c)) calc(var(--fx-h) + 28) / .5); animation-name: fx-drift-2; animation-duration: calc(41s / var(--fx-speed)); }
#fathom-wall .fx-b3 { left: 20vmax; bottom: -40vmax; background-color: oklch(.46 calc(.1 * var(--fx-c)) calc(var(--fx-h) - 30) / .35); animation-name: fx-drift-3; animation-duration: calc(47s / var(--fx-speed)); }
#fathom-wall .fx-b4 { right: -10vmax; bottom: -30vmax; width: 60vmax; height: 60vmax; opacity: 0; background-color: var(--fx-art);
  animation-name: fx-drift-2; animation-duration: calc(52s / var(--fx-speed)); }
html[data-fx-arttint="on"] #fathom-wall .fx-b4 { opacity: .3; }
#fathom-wall .fx-rays { position: absolute; inset: -20%; opacity: .5; display: none;
  background: repeating-linear-gradient(105deg, transparent 0 60px, oklch(.86 calc(.08 * var(--fx-c)) var(--fx-h) / .04) 60px 64px, transparent 64px 140px);
  -webkit-mask: radial-gradient(60% 50% at 40% 20%, #000, transparent); mask: radial-gradient(60% 50% at 40% 20%, #000, transparent);
  animation: fx-rays calc(26s / var(--fx-speed)) steps(312, jump-none) infinite; }
html[data-fx-rays="on"] #fathom-wall .fx-rays { display: block; }
#fathom-wall .fx-image { position: absolute; inset: 0; display: none; background: var(--fx-wall-image) center / cover no-repeat; }
#fathom-wall .fx-image::after { content: ""; position: absolute; inset: 0; background: #04070c; opacity: var(--fx-wall-dim); }
/* Normal blending on purpose: a full-screen blend mode makes the compositor redo the whole wallpaper each frame. */
#fathom-wall .fx-grain { position: absolute; inset: 0; opacity: calc(var(--fx-grain) * .7);
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>"); }
#fathom-wall .fx-vignette { position: absolute; inset: 0; background: radial-gradient(120% 90% at 50% 40%, transparent 55%, rgb(0 0 0 / .55)); }

html[data-fx-wall="still"] #fathom-wall .fx-blob,
html[data-fx-wallmotion="off"] #fathom-wall .fx-blob,
html[data-fx-wallmotion="off"] #fathom-wall .fx-rays { animation: none; }
html[data-fx-wall="abyss"] #fathom-wall { background-color: oklch(.09 calc(.015 * var(--fx-c)) var(--fx-h)); }
html[data-fx-wall="abyss"] #fathom-wall .fx-blob:not(.fx-b4) { display: none; }
html[data-fx-wall="image"] #fathom-wall .fx-image { display: block; }
html[data-fx-wall="image"] #fathom-wall .fx-blob, html[data-fx-wall="image"] #fathom-wall .fx-rays { display: none; }
html[data-fx-wall="harbor"] #fathom-wall { display: none; }
html[data-chrome-hidden] #fathom-wall *, html[data-fx-scrolling] #fathom-wall * { animation-play-state: paused; }
html[data-fx][data-fx-everywhere="on"]:not([data-fx-wall="harbor"]) main.bg-canvas { background-color: transparent !important; }

@keyframes fx-drift-1 { to { transform: translate(18vmax, 12vmax) scale(1.1); } }
@keyframes fx-drift-2 { to { transform: translate(-16vmax, -10vmax) scale(.92); } }
@keyframes fx-drift-3 { to { transform: translate(-12vmax, -14vmax) scale(1.15); } }
@keyframes fx-rays { to { transform: translateX(140px); } }

/* 6. Chrome ------------------------------------------------------------- */
#fathom-chrome .fx-ico { width: 20px; height: 20px; flex: none; }
/* Nav buttons. The selected one carries a glass pill; .fx-morph is the pill in flight between items. */
.fx-nb { position: relative; z-index: 1; isolation: isolate; border: 0; background: none; cursor: pointer;
  transition: transform .35s var(--fx-spring), opacity .2s ease, color .2s ease; }
.fx-nb:active { transform: scale(.9); transition-duration: .12s; }
.fx-nb[data-active]::before, .fx-morph {
  background: color-mix(in oklab, var(--color-accent) 16%, rgb(255 255 255 / .1));
  box-shadow: inset 0 1px .5px rgb(255 255 255 / .42), inset 0 -1px .5px rgb(255 255 255 / .1), inset 0 0 0 .5px rgb(255 255 255 / .18), 0 6px 16px -8px rgb(0 0 0 / .6);
}
.fx-nb[data-active]::before { content: ""; position: absolute; inset: 3px; z-index: -1; border-radius: inherit; }
.fx-morph { position: absolute; z-index: 0; pointer-events: none; transform-origin: 0 0; will-change: transform; }
[data-fx-morphing] .fx-nb[data-active]::before { opacity: 0; }

/* menu bar */
#fx-menubar { position: fixed; inset: 0 0 auto 0; height: 40px; z-index: 60; display: flex; align-items: center; gap: 18px;
  padding: 0 156px 0 16px; font-size: 13px; border-radius: 0;
  box-shadow: inset 0 -.5px 0 rgb(255 255 255 / calc(var(--fx-rim) * .4)), 0 10px 30px -20px rgb(0 0 0 / .8); }
#fx-menubar > * { position: relative; z-index: 1; }
#fx-menubar .fx-brand { display: flex; align-items: center; gap: 8px; font-weight: 700; letter-spacing: -.01em; }
#fx-menubar .fx-brand .fx-ico { width: 16px; height: 16px; color: var(--color-accent); }
#fx-menubar .fx-where { color: var(--color-ink-muted); font-weight: 500; }
#fx-menubar .fx-where:empty { display: none; }
#fx-menubar .fx-links { position: relative; display: flex; gap: 2px; }
#fx-menubar .fx-link { padding: 6px 11px; border-radius: 9px; opacity: .74; }
#fx-menubar .fx-link:hover, #fx-menubar .fx-link[data-active] { opacity: 1; }
#fx-menubar .fx-right { margin-inline-start: auto; display: flex; align-items: center; gap: 6px; }
#fx-menubar .fx-ib { border: 0; background: none; width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; cursor: pointer; opacity: .8; transition: background .2s, opacity .2s; }
#fx-menubar .fx-ib:hover { opacity: 1; background: rgb(255 255 255 / .08); }
#fx-menubar .fx-ib .fx-ico { width: 16px; height: 16px; }
#fx-menubar .fx-clock { font-variant-numeric: tabular-nums; opacity: .88; padding: 0 6px; white-space: nowrap; }

/* dock: glyphs sit directly on the glass; no tiles */
#fx-dock { position: fixed; z-index: 60; display: flex; align-items: flex-end; gap: 4px; padding: 7px;
  border-radius: calc(var(--fx-dock-size) * .5 + 7px);
  left: 50%; bottom: 12px; translate: -50% 0;
  transition: translate calc(.45s / var(--fx-speed)) var(--fx-ease), background-color 1.2s; }
html[data-fx-dockpos="left"] #fx-dock { flex-direction: column; align-items: flex-start; left: 12px; top: 50%; bottom: auto; translate: 0 -50%; }
html[data-fx-autohide="on"]:not([data-fx-reveal]) #fx-dock { translate: -50% calc(100% + 30px); }
html[data-fx-autohide="on"][data-fx-dockpos="left"]:not([data-fx-reveal]) #fx-dock { translate: calc(-100% - 30px) -50%; }
#fx-dock .fx-di { --s: 1; flex: none; padding: 0; display: grid; place-items: center; color: var(--color-ink); opacity: .78;
  width: calc(var(--fx-dock-size) * var(--s)); height: calc(var(--fx-dock-size) * var(--s)); border-radius: 50%;
  transition: width .16s ease, height .16s ease, transform .35s var(--fx-spring), opacity .2s ease, color .2s ease; }
#fx-dock .fx-di .fx-ico { width: calc(22px * var(--s)); height: calc(22px * var(--s)); transition: width .16s ease, height .16s ease; }
#fx-dock .fx-di:hover { opacity: 1; }
#fx-dock .fx-di[data-active] { opacity: 1; color: var(--color-accent); }
#fx-dock .fx-sep { flex: none; width: 1px; align-self: stretch; margin: 10px 3px; background: rgb(255 255 255 / .14); position: relative; z-index: 1; }
html[data-fx-dockpos="left"] #fx-dock .fx-sep { width: auto; height: 1px; margin: 3px 10px; }
.fx-tip { position: absolute; pointer-events: none; white-space: nowrap; font-size: 12px; font-weight: 550; padding: 5px 10px; border-radius: 9px;
  background: oklch(.2 var(--fx-gc) var(--fx-h) / .94); color: var(--color-ink); box-shadow: inset 0 0 0 .5px rgb(255 255 255 / .16), 0 8px 20px -8px rgb(0 0 0 / .7);
  opacity: 0; transition: opacity .15s, transform .2s var(--fx-ease); z-index: 3; }
#fx-dock .fx-tip { bottom: calc(100% + 14px); left: 50%; transform: translate(-50%, 4px); }
html[data-fx-dockpos="left"] #fx-dock .fx-tip { bottom: auto; left: calc(100% + 14px); top: 50%; transform: translate(-4px, -50%); }
html[data-fx-labels="on"] #fx-dock .fx-di:hover .fx-tip, html[data-fx-labels="on"] #fx-dock .fx-di:focus-visible .fx-tip { opacity: 1; transform: translate(-50%, 0); }
html[data-fx-labels="on"][data-fx-dockpos="left"] #fx-dock .fx-di:hover .fx-tip { transform: translate(0, -50%); }

/* sidebar */
#fx-sidebar { position: fixed; z-index: 60; left: 12px; top: calc(var(--fx-top) + 12px); bottom: 12px; width: var(--fx-sidebar-w);
  display: flex; flex-direction: column; gap: 2px; padding: 12px 9px; border-radius: var(--fx-radius); overflow: hidden auto; scrollbar-width: none; }
#fx-sidebar .fx-si { display: flex; align-items: center; gap: 12px; padding: 10px 13px; border-radius: 13px; font-size: 14px; text-align: start; opacity: .78; }
#fx-sidebar .fx-si .fx-ico { width: 18px; height: 18px; }
#fx-sidebar .fx-si:hover { opacity: 1; }
#fx-sidebar .fx-si[data-active] { opacity: 1; }
#fx-sidebar .fx-si[data-active] .fx-ico { color: var(--color-accent); }
#fx-sidebar .fx-grow { flex: 1; }
html[data-fx-compact="on"] #fx-sidebar { width: 64px; padding: 10px 7px; }
html[data-fx-compact="on"] #fx-sidebar .fx-si span { display: none; }
html[data-fx-compact="on"] #fx-sidebar .fx-si { justify-content: center; padding: 13px 0; }

/* island */
#fx-island { position: fixed; z-index: 60; top: 10px; left: 50%; translate: -50% 0; display: flex; align-items: center; gap: 2px; padding: 5px; border-radius: 999px;
  max-width: calc(100vw - 340px); overflow-x: auto; scrollbar-width: none; }
#fx-island .fx-ii { padding: 8px 14px; border-radius: 999px; font-size: 13px; opacity: .76; display: flex; align-items: center; gap: 8px; white-space: nowrap; }
#fx-island .fx-ii .fx-ico { width: 15px; height: 15px; display: none; }
#fx-island .fx-ii:hover { opacity: 1; }
#fx-island .fx-ii[data-active] { opacity: 1; }
#fx-island .fx-ii[data-active] .fx-ico { display: block; color: var(--color-accent); }
#fx-island .fx-ii.fx-iconly { padding: 8px 10px; }
#fx-island .fx-ii.fx-iconly .fx-ico { display: block; }
#fx-island .fx-clock { position: relative; z-index: 1; padding: 0 12px 0 6px; font-size: 13px; opacity: .85; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* toast */
#fathom-toast { position: fixed; z-index: 206; left: 50%; bottom: calc(var(--fx-dock-size) + 64px); translate: -50% 0; display: flex; align-items: center; gap: 12px;
  padding: 10px 10px 10px 16px; border-radius: 18px; font-size: 13px; animation: fx-in .5s var(--fx-ease) both; }
#fathom-toast > * { position: relative; z-index: 1; }
#fathom-toast kbd { font: 600 11px var(--fx-ui); padding: 2px 6px; border-radius: 6px; background: rgb(255 255 255 / .14); }
#fathom-toast button { border: 0; cursor: pointer; padding: 6px 12px; border-radius: 10px; background: rgb(255 255 255 / .12); }
@keyframes fx-in { from { opacity: 0; transform: translateY(10px); } }
@keyframes fx-fade { from { opacity: 0; } }

/* 7. Settings panel -----------------------------------------------------
   Denser glass than the chrome and no tilt, so text stays readable over bright artwork. */
#fathom-panel { --fx-ga: .8;
  position: fixed; z-index: 205; top: calc(var(--fx-top) + 12px); right: 12px; bottom: 12px; width: min(392px, calc(100vw - 24px));
  display: flex; flex-direction: column; border-radius: var(--fx-radius); font-size: 13px; overflow: hidden;
  transition: opacity .3s ease, translate .45s var(--fx-ease), visibility 0s linear 0s, background-color 1.2s; }
#fathom-panel[hidden] { display: flex; visibility: hidden; opacity: 0; translate: 24px 0; pointer-events: none; transition: opacity .25s ease, translate .35s var(--fx-ease), visibility 0s linear .35s; }
#fathom-panel > * { position: relative; z-index: 1; }
.fx-ph { display: flex; align-items: center; gap: 10px; padding: 16px 16px 10px 18px; }
.fx-ph .fx-title { font-size: 16px; font-weight: 650; letter-spacing: -.01em; }
.fx-ph .fx-sub { font-size: 12px; color: color-mix(in oklab, var(--color-ink) 68%, transparent); margin-top: 2px; }
.fx-ph .fx-x { margin-inline-start: auto; border: 0; width: 30px; height: 30px; border-radius: 50%; background: rgb(255 255 255 / .08); cursor: pointer; display: grid; place-items: center; }
.fx-ph .fx-x:hover { background: rgb(255 255 255 / .16); }
.fx-ph .fx-x .fx-ico { width: 15px; height: 15px; }
.fx-tabs { display: flex; gap: 2px; margin: 0 12px; padding: 3px; border-radius: 13px; background: rgb(0 0 0 / .28); overflow-x: auto; scrollbar-width: none; flex: none; }
.fx-tabs button { flex: 1; border: 0; background: none; padding: 7px 6px; border-radius: 10px; cursor: pointer; font-size: 12.5px; opacity: .72; white-space: nowrap; }
.fx-tabs button[aria-selected="true"] { background: rgb(255 255 255 / .14); opacity: 1; box-shadow: inset 0 1px 0 rgb(255 255 255 / .2); }
.fx-body { flex: 1; overflow-y: auto; padding: 4px 18px 22px; scrollbar-width: thin; scrollbar-color: rgb(255 255 255 / .2) transparent; }
.fx-body h3 { margin: 18px 0 6px; padding-top: 16px; border-top: 1px solid rgb(255 255 255 / .08); font-size: 13.5px; font-weight: 650; letter-spacing: -.005em; color: var(--color-ink); }
.fx-body h3:first-child { margin-top: 8px; padding-top: 0; border-top: 0; }
.fx-body .fx-hint { font-size: 12px; color: color-mix(in oklab, var(--color-ink) 70%, transparent); margin: -2px 0 8px; line-height: 1.45; }
.fx-row { display: grid; grid-template-columns: 1fr auto; gap: 6px 10px; align-items: center; margin: 10px 0; }
.fx-row > span { opacity: .92; }
.fx-row output { font-variant-numeric: tabular-nums; color: color-mix(in oklab, var(--color-ink) 72%, transparent); font-size: 12px; }
.fx-row input[type=range] { grid-column: 1 / -1; width: 100%; appearance: none; height: 4px; border-radius: 4px; outline-offset: 6px;
  background: linear-gradient(90deg, var(--color-accent) var(--fx-fill, 50%), rgb(255 255 255 / .14) var(--fx-fill, 50%)); }
